<?php
declare(strict_types=1);
namespace App\Controllers\Admin;
use App\Core\{AppKernel,Request,Response};
use App\Domain\Deliveries\DeliveryRules as Rules;
final class DeliveriesController extends AdminController {
 private function allowed(int $id,string $permission):?array{return AppKernel::access()->accessibleBranchIdsForPermission($id,'deliveries.'.$permission);}
 private function missing($u):Response{return $this->adminView('admin/error',['title'=>'Entrega no disponible','message'=>'El documento no existe o está fuera de tu alcance.','user'=>$u],404);}
 public function index(Request $r):Response{$u=$this->requireUser();if($u instanceof Response)return $u;$allowed=$this->allowed($u->id,'view');if($allowed===[])return $this->requirePermission($u,'deliveries.view')??Response::redirect('/admin');return $this->adminView('admin/deliveries/index',['title'=>'Entregas','activeNav'=>'deliveries','user'=>$u,'page'=>AppKernel::deliveries()->listing($r->query('q'),$r->query('status'),$r->integer('branch_id')?:null,$allowed,max(0,(int)$r->query('offset','0'))),'q'=>$r->query('q'),'status'=>$r->query('status'),'branchId'=>$r->integer('branch_id'),'branches'=>array_filter(AppKernel::transfers()->branches(),fn($b)=>$allowed===null||in_array((int)$b['id'],$allowed,true)),'canCreate'=>$this->allowed($u->id,'create')!==[],'canResources'=>$this->allowed($u->id,'resources')!==[]]);}
 public function createForm(Request $r,array $values=[],?string $error=null):Response{$u=$this->requireUser();if($u instanceof Response)return $u;$allowed=$this->allowed($u->id,'create');if($allowed===[])return $this->requirePermission($u,'deliveries.create')??Response::redirect('/admin');$version=(int)($values['quote_version_id']??$r->query('quote_version_id','0'));$quote=$version?AppKernel::deliveries()->quote($version,$allowed):null;if($version&&(!$quote||$quote['quote_status']!=='accepted'))return $this->missing($u);$items=$quote?AppKernel::deliveries()->quoteItems($version):[];if($quote){$quote['customer_name']=json_decode($quote['customer_snapshot'],true,512,JSON_THROW_ON_ERROR)['legal_name']??'';$quote['branch_name']=json_decode($quote['branch_snapshot'],true,512,JSON_THROW_ON_ERROR)['name']??'';}$res=AppKernel::deliveryReservations();foreach($items as &$i)$i['reserved_quantity']=$res->available($version,(int)$i['id'],(int)$i['variant_id']);unset($i);return $this->adminView('admin/deliveries/create',['title'=>'Crear entrega','activeNav'=>'deliveries','user'=>$u,'values'=>$values?:['quote_version_id'=>$version,'operation_key'=>bin2hex(random_bytes(20))],'error'=>$error,'quote'=>$quote,'items'=>$items,'q'=>$r->query('q'),'options'=>AppKernel::deliveries()->options($r->query('q'),$allowed,max(0,(int)$r->query('offset','0')))],$error?422:200);}
 public function create(Request $r):Response{$u=$this->requireUser();if($u instanceof Response)return $u;if($e=$this->requireCsrf($r,$u))return $e;$allowed=$this->allowed($u->id,'create');if($allowed===[])return $this->requirePermission($u,'deliveries.create')??Response::redirect('/admin');$input=[];foreach(['quote_version_id','operation_key','mode','address','location_reference','scheduled_date','receiver','delivery_cost']as $k)$input[$k]=$r->input($k);try{$id=AppKernel::deliveryManagement()->create($input,$r->keyedValues('quantity'),$allowed,$u->id,fn($id,$b,$a)=>AppKernel::audit()->record($u->id,'delivery.'.$a,'delivery',$id,$b,'success'));return Response::redirect('/admin/deliveries/detail?id='.$id);}catch(\InvalidArgumentException|\App\Application\Exceptions\ApplicationException $e){$error=$e->getMessage();}catch(\Throwable){$error='No se pudo crear la entrega. No se confirmaron cambios.';}$input['quantities']=$r->keyedValues('quantity');return $this->createForm($r,$input,$error);}
 public function detail(Request $r):Response{$u=$this->requireUser();if($u instanceof Response)return $u;$allowed=$this->allowed($u->id,'view');if($allowed===[])return $this->requirePermission($u,'deliveries.view')??Response::redirect('/admin');$d=AppKernel::deliveries()->find($r->integer('id'),$allowed);if(!$d)return $this->missing($u);$actions=[];foreach(array_keys(Rules::ACTIONS)as $a)$actions[$a]=AppKernel::access()->hasPermission($u->id,'deliveries.'.($a==='retry'?'incident':$a),(int)$d['branch_id']);$history=AppKernel::access()->hasPermission($u->id,'deliveries.history',(int)$d['branch_id']);return $this->adminView('admin/deliveries/detail',['title'=>$d['folio'],'activeNav'=>'deliveries','user'=>$u,'delivery'=>$d,'selectedAction'=>$r->query('action'),'items'=>AppKernel::deliveries()->items((int)$d['id']),'pending'=>AppKernel::deliveries()->quoteItems((int)$d['quote_version_id']),'history'=>$history?AppKernel::deliveries()->history((int)$d['id']):[],'actions'=>$actions,'canEvidence'=>AppKernel::cms()->installed()&&(AppKernel::access()->hasPermission($u->id,'media.evidence.view',(int)$d['branch_id'])),'stop'=>AppKernel::deliveries()->stop((int)$d['id'])]);}
 public function action(Request $r):Response{$u=$this->requireUser();if($u instanceof Response)return $u;if($e=$this->requireCsrf($r,$u))return $e;$a=$r->input('action');if(!isset(Rules::ACTIONS[$a]))return $this->missing($u);$permission=$a==='retry'?'incident':$a;$allowed=$this->allowed($u->id,$permission);if($allowed===[])return $this->requirePermission($u,'deliveries.'.$permission)??Response::redirect('/admin');$id=$r->integer('id');$d=AppKernel::deliveries()->find($id,$allowed);if(!$d)return $this->missing($u);$branch=(int)$d['branch_id'];if($e=$this->requirePermission($u,'deliveries.'.$permission,$branch))return $e;
  if(in_array($a,['dispatch','confirm','cancel'],true)&&$r->input('physical_confirmation')!=='1')return $this->run(fn()=>throw new \InvalidArgumentException('Confirma explícitamente la operación.'),'','/admin/deliveries/detail?id='.$id);
  return $this->run(fn()=>AppKernel::deliveryManagement()->action($id,(int)$r->input('lock_version'),$a,$r->keyedValues('quantity'),$r->input('operation_key'),$r->input('notes'),$r->input('receiver'),['run_id'=>$r->input('run_id'),'position'=>$r->input('position')],$allowed,$u->id,fn($id,$b,$action)=>AppKernel::audit()->record($u->id,'delivery.'.$action,'delivery',$id,$b,'success')),'Operación confirmada.','/admin/deliveries/detail?id='.$id,$u->id,'delivery.'.$a,'delivery',$id,$branch);
 }
 public function resources(Request $r):Response{$u=$this->requireUser();if($u instanceof Response)return $u;$allowed=$this->allowed($u->id,'resources');if($allowed===[])return $this->requirePermission($u,'deliveries.resources')??Response::redirect('/admin');$kind=$r->query('kind','vehicles');if(!in_array($kind,['vehicles','drivers','delivery_runs'],true))return $this->missing($u);return $this->adminView('admin/deliveries/resources',['title'=>'Recursos de entrega','activeNav'=>'deliveries','user'=>$u,'vehicleOptions'=>$kind==='delivery_runs'&&$r->query('new')==='1'?$this->resourceOptions('vehicles',$allowed):[],'driverOptions'=>$kind==='delivery_runs'&&$r->query('new')==='1'?$this->resourceOptions('drivers',$allowed):[],'kind'=>$kind,'resourceId'=>$r->integer('resource_id'),'showResourceForm'=>$r->query('new')==='1','page'=>AppKernel::deliveries()->resources($kind,$allowed,max(0,(int)$r->query('offset','0'))),'branches'=>array_filter(AppKernel::transfers()->branches(),fn($b)=>$allowed===null||in_array((int)$b['id'],$allowed,true))]);}
 private function resourceOptions(string $kind,?array $allowed):array {
  $options=[];$offset=0;
  do {
   $page=AppKernel::deliveries()->resources($kind,$allowed,$offset);
   foreach($page->items as $resource)if((int)$resource['is_active']===1&&(int)$resource['is_available']===1)$options[]=['id'=>$resource['id'],'name'=>$resource['name'],'code'=>$resource['code'],'branch_id'=>$resource['branch_id']];
   $offset+=$page->limit;
  }while($page->hasMore);
  return $options;
 }
 public function saveResource(Request $r):Response{$u=$this->requireUser();if($u instanceof Response)return $u;if($e=$this->requireCsrf($r,$u))return $e;$allowed=$this->allowed($u->id,'resources');if($allowed===[])return $this->requirePermission($u,'deliveries.resources')??Response::redirect('/admin');$kind=$r->input('kind');if(!in_array($kind,['vehicles','drivers','delivery_runs'],true))return $this->missing($u);$input=[];foreach(['id','lock_version','operation_key','branch_id','name','code','is_active','is_available','scheduled_date','vehicle_id','driver_id']as $k)$input[$k]=$r->input($k);return $this->run(fn()=>AppKernel::deliveryManagement()->saveResource($kind,$input,$allowed,$u->id,fn($id,$b,$a)=>AppKernel::audit()->record($u->id,'delivery.resource','delivery_resource',$id,$b,'success')),'Recurso guardado.','/admin/deliveries/resources?kind='.$kind,$u->id,'delivery.resource');}
}
